part of 'academy_english_advanced_models.dart';
abstract final class EnglishAdvancedB1SevenToTen {
 static const lessons = <EnglishAdvancedLesson>[
    EnglishAdvancedLesson(level:'B1',unitNumber:1,number:7,title:"A Small Business Idea",titleArabic:"فكرة مشروع صغير",storyTitle:"A Small Business Idea",storyTitleArabic:"فكرة مشروع صغير",paragraphs:<String>["Kareem began making furniture in his grandfather's garage. A neighbor loved the wooden chair he had restored and asked for a matching table. Kareem realised that his hobby might support a small business.","He prepared a business plan, calculated start-up costs and built a product catalogue. A friend suggested a new brand name and helped him open an online shop. Careful photographs brought his first orders.","One customer complained that a table had arrived scratched. Kareem offered a repair and improved the packaging. He also explained the shop's return policy and invited honest feedback.","Several months later, Kareem had a growing customer base. He chose to expand slowly rather than borrow money immediately. He discovered that trustworthy service was as valuable as skilled craftsmanship."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("grandfather's garage","مرآب الجد"),EnglishAdvancedWord("wooden chair","كرسي خشبي"),EnglishAdvancedWord("matching table","طاولة مطابقة"),EnglishAdvancedWord("business plan","خطة عمل"),EnglishAdvancedWord("start-up costs","تكاليف التأسيس"),EnglishAdvancedWord("product catalogue","كتالوج منتجات"),EnglishAdvancedWord("brand name","اسم تجاري"),EnglishAdvancedWord("online shop","متجر إلكتروني"),EnglishAdvancedWord("offered a repair","عرض إصلاحًا"),EnglishAdvancedWord("shop's return policy","سياسة إرجاع المتجر"),EnglishAdvancedWord("customer base","قاعدة عملاء"),EnglishAdvancedWord("craftsmanship","حرفية الصنع")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("price quotation","عرض سعر"),EnglishAdvancedWord("inventory sheet","سجل مخزون"),EnglishAdvancedWord("delivery tracking","تتبع الشحن"),EnglishAdvancedWord("revenue forecast","توقع الإيرادات"),EnglishAdvancedWord("retail packaging","تغليف تجاري"),EnglishAdvancedWord("materials budget","ميزانية مواد"),EnglishAdvancedWord("online order confirmation","تأكيد طلب"),EnglishAdvancedWord("handmade goods","منتجات يدوية"),EnglishAdvancedWord("workshop insurance","تأمين الورشة"),EnglishAdvancedWord("sales invoice","فاتورة بيع"),EnglishAdvancedWord("repeat buyer","مشتري متكرر"),EnglishAdvancedWord("product warranty","ضمان منتج"),EnglishAdvancedWord("online storefront","واجهة متجر إلكتروني"),EnglishAdvancedWord("wholesale purchase","شراء بالجملة"),EnglishAdvancedWord("assembly instructions","تعليمات التركيب"),EnglishAdvancedWord("wood stain","صبغة أخشاب"),EnglishAdvancedWord("quality checklist","قائمة جودة"),EnglishAdvancedWord("craft market stall","كشك سوق حرفي")],grammarTitle:"Gerunds and infinitives",grammarArabic:"يأتي بعد enjoy فعل ينتهي بـ ing مثل enjoy repairing، بينما يأتي بعد decide وhope غالبًا to + فعل أساسي مثل decided to open. تعلم تركيب الفعل مع معناه.",grammarExamples:<String>["He enjoys restoring furniture.","Kareem decided to open a shop.","They hope to welcome more customers."],listening:"Good evening, and welcome to the small business workshop. Kareem will explain how he turned a hobby into an online shop. The session begins at six thirty in the upstairs meeting room. Visitors can examine example products, but orders will not be taken during the presentation. Kareem will also describe how he responded when a customer reported a damaged table. After the talk, please collect an information sheet if you would like to ask about custom furniture or delivery arrangements.",listeningQuestion:"Why did Kareem change his packaging?",listeningOptions:<String>["A table was damaged during delivery","He started selling food","He moved to another town"],listeningAnswer:0,readingQuestion:"What did Kareem learn from his first customer complaint?",readingOptions:<String>["Stop selling furniture","Offer repairs and improve service","Avoid discussing problems"],readingAnswer:1,writingCue:"Kareem valued skilled ____ as much as honest service.",writingAnswer:"craftsmanship"),
    EnglishAdvancedLesson(level:'B1',unitNumber:1,number:8,title:"Organizing a Charity Run",titleArabic:"تنظيم سباق خيري",storyTitle:"Organizing a Charity Run",storyTitleArabic:"تنظيم سباق خيري",paragraphs:<String>["Mariam helped organize a charity run to support a children's hospital. The committee planned a five-kilometre route around the park and needed volunteers to supervise the finish line.","She designed a registration form and arranged a water station and a first-aid tent. A volunteer marshal inspected the starting point while local businesses donated small prizes.","On the morning of the event, unexpected roadworks blocked the entrance. The route supervisor designed an alternative path, and Mariam used a loudspeaker to explain the change. Runners followed the new signs.","After the race, hospital staff thanked the participants. The donations exceeded the original target. Mariam realised that effective teamwork requires careful planning and the flexibility to solve problems."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("charity run","سباق خيري"),EnglishAdvancedWord("children's hospital","مستشفى أطفال"),EnglishAdvancedWord("five-kilometre route","مسار خمسة كيلومترات"),EnglishAdvancedWord("supervise the finish line","خط النهاية"),EnglishAdvancedWord("designed a registration form","استمارة تسجيل"),EnglishAdvancedWord("water station","محطة مياه"),EnglishAdvancedWord("first-aid tent","خيمة إسعاف"),EnglishAdvancedWord("volunteer marshal","منظم متطوع"),EnglishAdvancedWord("starting point","نقطة بداية"),EnglishAdvancedWord("unexpected roadworks","أشغال طريق مفاجئة"),EnglishAdvancedWord("route supervisor","مشرف المسار"),EnglishAdvancedWord("loudspeaker","مكبر صوت")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("race bib","رقم العداء"),EnglishAdvancedWord("timing chip","شريحة توقيت"),EnglishAdvancedWord("hydration point","نقطة شرب"),EnglishAdvancedWord("safety briefing","إحاطة سلامة"),EnglishAdvancedWord("participant waiver","إقرار مشاركة"),EnglishAdvancedWord("course map","خريطة المسار"),EnglishAdvancedWord("warm-up session","جلسة إحماء"),EnglishAdvancedWord("finishers' medal","ميدالية إكمال"),EnglishAdvancedWord("donation bucket","دلو تبرعات"),EnglishAdvancedWord("race steward","مشرف السباق"),EnglishAdvancedWord("access gate","بوابة الدخول"),EnglishAdvancedWord("medical tent","خيمة طبية"),EnglishAdvancedWord("route diversion","تحويل مسار"),EnglishAdvancedWord("runner's pace","وتيرة العداء"),EnglishAdvancedWord("lap counter","عداد الدورات"),EnglishAdvancedWord("support station","محطة دعم"),EnglishAdvancedWord("community race","سباق مجتمعي"),EnglishAdvancedWord("event wristband","سوار الفعالية")],grammarTitle:"Reported questions",grammarArabic:"نحوّل السؤال المباشر إلى سؤال غير مباشر بترتيب الجملة الخبرية: Where is the start? تصبح She asked where the start was. ونستخدم asked + شخص + to + فعل لنقل الطلب.",grammarExamples:<String>["She asked where the entrance was.","They wanted to know whether the race would start on time.","The organizer asked the runners to wait."],listening:"Good morning, everyone. Due to roadworks, the eastern entrance to the park is closed. All runners should use the western entrance and follow the blue arrows. The charity run will still begin at nine thirty. The warm-up session has been moved beside the fountain, and the medical volunteers are waiting near the finish line. Please keep your registration number visible. If you have questions, ask a marshal wearing a yellow jacket. Do not use any path marked with a red barrier.",listeningQuestion:"Which entrance must the runners use?",listeningOptions:<String>["The eastern gate","The western gate","The hospital gate"],listeningAnswer:1,readingQuestion:"How did Mariam respond to the roadworks?",readingOptions:<String>["She cancelled the run","She announced an alternative path","She ignored the problem"],readingAnswer:1,writingCue:"Mariam made the announcement through a ____.",writingAnswer:"loudspeaker"),
    EnglishAdvancedLesson(level:'B1',unitNumber:1,number:9,title:"The Community Garden",titleArabic:"الحديقة المجتمعية",storyTitle:"The Community Garden",storyTitleArabic:"الحديقة المجتمعية",paragraphs:<String>["An unused patch of land behind the sports centre was offered to local families. They decided to build a community garden where neighbours could meet, grow vegetables and learn together.","The coordinator prepared planting plots and arranged a composting workshop. A landscape designer created a seasonal planting calendar, while volunteers built a raised bed for older gardeners.","Some residents wanted vegetables, whereas others preferred a quiet seating area surrounded by flowers. The group agreed to allocate separate sections so everyone could enjoy the space.","When the first harvest arrived, neighbours shared fresh produce and recipes. The garden had created friendships between people who had rarely spoken before. The project became a meeting place as much as a place to grow food."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("unused patch of land","أرض مهجورة"),EnglishAdvancedWord("community garden","حديقة مجتمعية"),EnglishAdvancedWord("planting plots","أحواض زراعة"),EnglishAdvancedWord("composting workshop","ورشة سماد عضوي"),EnglishAdvancedWord("landscape designer","مصمم حدائق"),EnglishAdvancedWord("seasonal planting calendar","تقويم زراعة موسمي"),EnglishAdvancedWord("raised bed","حوض زراعة مرتفع"),EnglishAdvancedWord("older gardeners","مزارعون كبار السن"),EnglishAdvancedWord("quiet seating area","مساحة جلوس هادئة"),EnglishAdvancedWord("allocate separate sections","تقسيم المساحة لأقسام"),EnglishAdvancedWord("first harvest","الحصاد الأول"),EnglishAdvancedWord("shared fresh produce","محاصيل طازجة")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("soil drainage","تصريف التربة"),EnglishAdvancedWord("seedling exchange","تبادل شتلات"),EnglishAdvancedWord("crop rotation","تناوب المحاصيل"),EnglishAdvancedWord("mulching layer","غطاء التربة"),EnglishAdvancedWord("pollinator shelter","مأوى الملقحات"),EnglishAdvancedWord("shared tool shed","مخزن أدوات مشترك"),EnglishAdvancedWord("watering rota","جدول السقي"),EnglishAdvancedWord("urban agriculture","زراعة حضرية"),EnglishAdvancedWord("local biodiversity","تنوع حيوي محلي"),EnglishAdvancedWord("organic gardening","زراعة عضوية"),EnglishAdvancedWord("community allotment","قطعة أرض مشتركة"),EnglishAdvancedWord("seed library","مكتبة بذور"),EnglishAdvancedWord("sustainable irrigation","ري مستدام"),EnglishAdvancedWord("soil health","صحة التربة"),EnglishAdvancedWord("rainwater collection","جمع مياه المطر"),EnglishAdvancedWord("garden pathway","ممر حديقة"),EnglishAdvancedWord("garden ledger","سجل الحديقة"),EnglishAdvancedWord("neighborhood gardening club","نادي بستنة الحي")],grammarTitle:"Contrast with whereas and although",grammarArabic:"نستخدم whereas لمقابلة فكرتين، وalthough للتعبير عن تناقض بين واقع ونتيجة. لا نستخدم although مع but في الجملة نفسها.",grammarExamples:<String>["Some wanted vegetables, whereas others chose flowers.","Although the area was small, it was useful.","While one group planted, another prepared the soil."],listening:"At our next community garden meeting, members will decide which plants to grow in the southern section. The northern beds will remain reserved for vegetables. On Saturday a horticulture teacher will explain how to rotate crops and protect the soil. New volunteers may borrow equipment from the shared shed, but they should return it before leaving. We also need two people to check the rainwater collection system. Anyone who needs easier access should speak with the coordinator before the planting session.",listeningQuestion:"What will happen at Saturday's gathering?",listeningOptions:<String>["A lesson about crop rotation","A trip to the airport","A school examination"],listeningAnswer:0,readingQuestion:"What resolved the residents' disagreement?",readingOptions:<String>["Closing the garden","Dividing the garden for different uses","Banning flowers"],readingAnswer:1,writingCue:"The community celebrated the ____ together.",writingAnswer:"first harvest"),
    EnglishAdvancedLesson(level:'B1',unitNumber:1,number:10,title:"Making a Difficult Choice",titleArabic:"اتخاذ قرار صعب",storyTitle:"Making a Difficult Choice",storyTitleArabic:"اتخاذ قرار صعب",paragraphs:<String>["Laila received two offers: a local training programme and an overseas exchange. Both seemed worthwhile, and she did not want to disappoint anyone who had encouraged her studies.","She listed the advantages and disadvantages, calculated living expenses and reflected on her long-term goals. A careers adviser helped her consider the practical support offered by each programme. Neither option promised a perfect outcome.","Her friend described adapting to a new culture after moving abroad. The experience had helped her gain independence, but had also been difficult at first. Laila realised that important decisions rarely come without uncertainty.","Finally, she chose the exchange and arranged weekly calls with her family. She knew her plans might change, but she felt confident in her reasons. She had learned to make a responsible decision without waiting for certainty."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("local training programme","تدريب محلي"),EnglishAdvancedWord("overseas exchange","تبادل خارجي"),EnglishAdvancedWord("worthwhile","جدير بالاهتمام"),EnglishAdvancedWord("disappoint anyone","يخيب أمل أحد"),EnglishAdvancedWord("advantages and disadvantages","إيجابيات وسلبيات"),EnglishAdvancedWord("living expenses","مصاريف معيشة"),EnglishAdvancedWord("long-term goals","أهداف بعيدة المدى"),EnglishAdvancedWord("careers adviser","مستشار مهني"),EnglishAdvancedWord("practical support","دعم عملي"),EnglishAdvancedWord("perfect outcome","نتيجة مثالية"),EnglishAdvancedWord("adapting to a new culture","تأقلم ثقافي"),EnglishAdvancedWord("independence","استقلالية")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("decision framework","إطار اتخاذ قرار"),EnglishAdvancedWord("personal priorities","أولويات شخصية"),EnglishAdvancedWord("opportunity cost","تكلفة الفرصة البديلة"),EnglishAdvancedWord("uncertainty tolerance","تحمل عدم اليقين"),EnglishAdvancedWord("career pathway","مسار مهني"),EnglishAdvancedWord("educational exchange","تبادل تعليمي"),EnglishAdvancedWord("support network","شبكة مساندة"),EnglishAdvancedWord("financial planning","تخطيط مالي"),EnglishAdvancedWord("prospective student","طالب محتمل"),EnglishAdvancedWord("cultural adjustment","تأقلم ثقافي شامل"),EnglishAdvancedWord("distance learning","تعلم عن بعد"),EnglishAdvancedWord("travel scholarship","منحة سفر"),EnglishAdvancedWord("personal development","تطور شخصي"),EnglishAdvancedWord("relocation expenses","تكاليف الانتقال"),EnglishAdvancedWord("mentorship session","جلسة إرشاد"),EnglishAdvancedWord("future prospects","آفاق مستقبلية"),EnglishAdvancedWord("responsible choice","خيار مسؤول"),EnglishAdvancedWord("evaluation criteria","معايير تقييم")],grammarTitle:"Modal verbs: advice, probability and obligation",grammarArabic:"نستخدم should للنصيحة وmight للاحتمال وmust للضرورة. يأتي بعد الأفعال الناقصة الفعل الأساسي من دون to عادة.",grammarExamples:<String>["You should compare the costs.","The exchange might be challenging.","She must check the application date."],listening:"If you are deciding between two study opportunities, start with the goals that matter most to you. Compare the fees, housing and support available in each programme. You should also speak to someone who has completed a similar course, while remembering that their experience may not match your own. Do not assume the most expensive choice is automatically the best. Your first decision does not have to shape your entire career. The strongest choice is one supported by clear reasons, even if some uncertainty remains.",listeningQuestion:"What does the speaker recommend?",listeningOptions:<String>["Select the most expensive programme","Compare costs, goals and support","Avoid asking others for advice"],listeningAnswer:1,readingQuestion:"Why did Laila eventually feel confident?",readingOptions:<String>["She knew every outcome","She understood her reasons for choosing","Her friend guaranteed success"],readingAnswer:1,writingCue:"Laila hoped to develop greater ____.",writingAnswer:"independence"),
 ];
}
